const token = $env.WHATSAPP_ACCESS_TOKEN || '';
const phoneId = $env.WHATSAPP_PHONE_NUMBER_ID || '';
const verifyToken = $env.WHATSAPP_VERIFY_TOKEN || 'snowcountry';
const coreUrl = ($env.SNOW_COUNTRY_N8N_CORE_URL || '').replace(/\/$/, '');

const method = $request.method || 'POST';
const query = $request.query || {};

if (method === 'GET') {
  const mode = query['hub.mode'];
  const challenge = query['hub.challenge'];
  const tokenQ = query['hub.verify_token'];
  if (mode === 'subscribe' && tokenQ === verifyToken) {
    return [{ json: { statusCode: 200, body: challenge, raw: true } }];
  }
  return [{ json: { statusCode: 403, body: 'Forbidden', raw: true } }];
}

const body = $json.body ?? $json;
const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;
const messages = value?.messages || [];

const outputs = [];
for (const msg of messages) {
  if (msg.type !== 'text') continue;
  const userId = msg.from;
  const text = msg.text?.body || '';

  const coreRes = await fetch(coreUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ channel: 'whatsapp', userId, message: text }),
  });
  const core = await coreRes.json();
  const replyText = core.replyText || '系統繁忙，請稍後再試。';

  if (token && phoneId) {
    await fetch('https://graph.facebook.com/v21.0/' + phoneId + '/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: 'Bearer ' + token,
      },
      body: JSON.stringify({
        messaging_product: 'whatsapp',
        to: userId,
        type: 'text',
        text: { body: replyText },
      }),
    });
  }
  outputs.push({ json: { userId, replyText } });
}

if (!outputs.length) outputs.push({ json: { ok: true } });
return outputs;
